    """Count number of islands (connected groups of '1') in a grid.
    Grid is list of list of ints/strings '0'/'1'. Connectivity 4-directional.
    """
    if not grid:
        return 0
    n=len(grid)
    m=len(grid[0])
    visited=[[False]*m for _ in range(n)]
    def dfs(i,j):
        stack=[(i,j)]
        while stack:
            x,y=stack.pop()
            if x<0 or x>=n or y<0 or y>=m:
                continue
            if visited[x][y]:
                continue
            if str(grid[x][y])!='1':
                continue
            visited[x][y]=True
            stack.extend([(x-1,y),(x+1,y),(x,y-1),(x,y+1)])
    count=0
    for i in range(n):
        for j in range(m):
            if not visited[i][j] and str(grid[i][j])=='1':
                dfs(i,j)
                count+=1
    return count
