    """Count islands in potentially irregular grid.
    grid: list of rows, each row is list of 0/1 (or int convertible).
    Connectivity 4-directional.
    """
    if not grid:
        return 0
    n = len(grid)
    visited = [ [False]*len(row) for row in grid ]
    def in_bounds(i, j):
        return 0 <= i < n and 0 <= j < len(grid[i])
    def is_land(i, j):
        val = grid[i][j]
        return val == 1 or val == '1'
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if not in_bounds(x, y) or visited[x][y] or not is_land(x, y):
