    n = len(nums)
    if n <= 1:
        return nums[:]
    # Find the first index i from the right where nums[i] < nums[i+1]
    i = n - 2
    while i >= 0 and nums[i] >= nums[i + 1]:
        i -= 1
    if i == -1:
        # Entire sequence is non-increasing, return sorted (smallest permutation)
        return sorted(nums)
    # Find the smallest element greater than nums[i] to the right
    j = n - 1
    while nums[j] <= nums[i]:
        j -= 1
    # Swap i and j
    nums[i], nums[j] = nums[j], nums[i]
    # Reverse the suffix after i
    nums[i+1:] = reversed(nums[i+1:])
    return nums"}

