    Grid is a list of rows, each row is a list of 0/1 values. Rows may have
    different lengths. Islands are groups of adjacent 1s (up, down, left, right).
    """
    if not grid:
        return 0
    m = len(grid)
    # visited mirrors the shape of grid
    visited = [ [False]*len(row) for row in grid ]
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if x < 0 or x >= m:
                continue
            if y < 0 or y >= len(grid[x]):
                continue
            if visited[x][y] or grid[x][y] == 0:
                continue
            visited[x][y] = True
            # neighbours
            stack.append((x-1, y))
            stack.append((x+1, y))
            stack.append((x, y-1))
            stack.append((x, y+1))
    islands = 0
    for i, row in enumerate(grid):
        for j in range(len(row)):
            if not visited[i][j] and row[j] == 1:
                dfs(i, j)
                islands += 1
    return islands

