    Supports '+', '-', '*', '/' where division truncates toward zero.
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                stack.append(a + b)
            elif tok == '-':
                stack.append(a - b)
            elif tok == '*':
                stack.append(a * b)
            else:  # division truncating toward zero
                # Perform division using absolute values to avoid float inaccuracies
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                sign = -1 if (a < 0) ^ (b < 0) else 1
                result = abs(a) // abs(b)
                stack.append(sign * result)
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

