    """Evaluate Reverse Polish Notation.
    Tokens are strings of integers or '+', '-', '*', '/'. Division truncates toward zero.
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                stack.append(a + b)
            elif tok == '-':
                stack.append(a - b)
            elif tok == '*':
                stack.append(a * b)
            else:  # division truncating toward zero
                # Using absolute division to avoid float inaccuracies
